// Accounts, end to end and local (PEP 0003): the real Worker under `wrangler dev` (Better Auth on a local D1, email
// codes instead of Google), the real folder-sync CLI built from this checkout, folder-sync's R2 stand-in
// (e2e/r2standin) in front of `rclone serve s3`. Two people, one machine each (two HOME dirs under a scratch dir).
// Fixture data only; test keys generated by scripts/dev.mjs; nothing leaves this machine.
//
//   [PROOF_DIR=<scratch>] [RCLONE=<pinned rclone>] [GO=<go>] node accounts/test/proof.mjs
//
// Ports (127.0.0.1): 4930 the R2 stand-in, 4931 the store, 4932 the accounts Worker (4942 its inspector); override with
// FS_STANDIN_PORT, FS_STORE_PORT, FS_ACCOUNTS_PORT, FS_INSPECTOR_PORT. What it proves, one PASS/FAIL line each:
// - a person signs in on the page by email code (/fs/dev/mailbox) and gets a host-only session cookie;
// - `folder-sync login` (the device grant) is approved by that browser session, stores account.json (0600), and then
//   folder-sync uses itself as the credential process: `init --project robotparts` and `sync --once` with no key;
// - a file PUT through /fs/v1/folders/robotparts/web/... lands on disk at <folder>/hosts/<web host id>/... after a sync;
// - a file written on disk is listed by /fs/v1/folders/robotparts and returned by its bundle;
// - another person cannot read the first one's folder (404), signed out is 401, public is readable signed out;
// - a cookie write without X-Folder-Sync: 1 is refused, a cookie never gets storage keys;
// - the web host's delete goes to _trash/ and leaves every machine; every request the stand-in let through used a
//   short-lived key inside its own root;
// - `folder-sync logout`, then `credentials` exits 3; signing the browser out makes /fs/v1/me 401.

import { spawn, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ACCOUNTS = resolve(fileURLToPath(new URL("..", import.meta.url)));
const REPO = resolve(ACCOUNTS, "..");
const DIR = resolve(process.env.PROOF_DIR || join(ACCOUNTS, ".state", "proof"));
const STATE = join(DIR, "stack");
const GO = process.env.GO || (existsSync(join(homedir(), ".local", "go", "bin", "go")) ? join(homedir(), ".local", "go", "bin", "go") : "go");
const RCLONE = resolve(process.env.RCLONE || join(REPO, ".tools", "rclone"));
const PROJECT = "robotparts";
const PEOPLE = { A: "maker@example.com", B: "stranger@example.com" };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const checks = [];
function check(name, ok, detail = "") {
	const text = typeof detail === "string" ? detail : JSON.stringify(detail);
	checks.push({ name, ok: !!ok, detail: text });
	console.log(`${ok ? "PASS" : "FAIL"} ${name}${text ? ` · ${text.slice(0, 220)}` : ""}`);
	return !!ok;
}

// ------------------------------------------------------------------------------------------------ the stack

function dev(verb) {
	const done = spawnSync(process.execPath, [join(ACCOUNTS, "scripts", "dev.mjs"), verb, "--state-dir", STATE], { encoding: "utf8", env: { ...process.env, RCLONE, GO } });
	const last = (done.stdout || "").trim().split("\n").pop() || "";
	if (done.status !== 0) throw new Error(`dev.mjs ${verb} exited ${done.status}: ${done.stderr}`);
	return JSON.parse(last);
}

function buildCli() {
	const bin = join(DIR, "bin", "folder-sync");
	const built = spawnSync(GO, ["-C", REPO, "build", "-ldflags", "-X main.version=v0-proof", "-o", bin, "./cmd/folder-sync"], { encoding: "utf8" });
	if (built.status !== 0) throw new Error(`folder-sync build failed: ${built.stderr}`);
	return bin;
}

// ------------------------------------------------------------------------------------------------ a browser, by hand

/** A cookie jar for one origin: what Set-Cookie said, sent back as Cookie. */
class Browser {
	constructor(site) {
		this.site = site;
		this.jar = new Map();
	}

	cookie() {
		return [...this.jar].map(([k, v]) => `${k}=${v}`).join("; ");
	}

	async fetch(path, { method = "GET", body, headers = {}, raw = false } = {}) {
		const h = { ...headers };
		if (this.jar.size) h.Cookie = this.cookie();
		if (body !== undefined && !raw) {
			h["Content-Type"] = "application/json";
			body = JSON.stringify(body);
		}
		const answer = await fetch(`${this.site}${path}`, { method, body, headers: h, redirect: "manual" });
		for (const line of answer.headers.getSetCookie()) {
			const [pair] = line.split(";");
			const at = pair.indexOf("=");
			const name = pair.slice(0, at).trim();
			const value = pair.slice(at + 1).trim();
			if (/max-age=0/i.test(line) || value === "") this.jar.delete(name);
			else this.jar.set(name, value);
		}
		return answer;
	}

	/** A write from this site's own page: its Origin, the CSRF header and, once signed in, the user it shows. */
	write(path, init = {}) {
		const user = this.userId ? { "X-Folder-Sync-User": this.userId } : {};
		return this.fetch(path, { ...init, headers: { Origin: this.site, "X-Folder-Sync": "1", ...user, ...(init.headers || {}) } });
	}
}

async function signIn(site, email) {
	const browser = new Browser(site);
	const sent = await browser.write("/fs/api/auth/email-otp/send-verification-otp", { method: "POST", body: { email, type: "sign-in" } });
	if (!sent.ok) throw new Error(`send code for ${email}: ${sent.status} ${await sent.text()}`);
	const { code } = await (await fetch(`${site}/fs/dev/mailbox?email=${encodeURIComponent(email)}`)).json();
	const signed = await browser.write("/fs/api/auth/sign-in/email-otp", { method: "POST", body: { email, otp: code } });
	if (!signed.ok) throw new Error(`sign in ${email}: ${signed.status} ${await signed.text()}`);
	browser.userId = (await (await browser.fetch("/fs/v1/me")).json()).user?.id;
	return browser;
}

// ------------------------------------------------------------------------------------------------ the machines

function envOf(home, site) {
	return { PATH: "/usr/bin:/bin", HOME: home, USERPROFILE: home, LANG: "C.UTF-8", FOLDER_SYNC_SERVER: site, FOLDER_SYNC_RCLONE: RCLONE };
}

function fsync(cli, home, site, args, input) {
	const done = spawnSync(cli, args, { cwd: home, env: envOf(home, site), encoding: "utf8", input, timeout: 180_000 });
	return { code: done.status, out: done.stdout || "", err: done.stderr || "" };
}

/** `folder-sync login` on a machine, approved through the Better Auth API by `browser` (the page's own two calls). */
async function login(cli, home, site, browser) {
	const child = spawn(cli, ["login"], { cwd: home, env: envOf(home, site) });
	let out = "";
	let err = "";
	child.stdout.on("data", (b) => { out += b; });
	child.stderr.on("data", (b) => { err += b; });
	const exited = new Promise((r) => child.on("exit", (code) => r(code)));
	const until = Date.now() + 30_000;
	while (!/open (\S+) and approve the code (\S+)/.test(out) && Date.now() < until) await sleep(200);
	const [, url, shown] = /open (\S+) and approve the code (\S+)/.exec(out) || [];
	if (!url) {
		child.kill();
		return { exit: await exited, out, err, url: null };
	}
	const userCode = shown.replace(/[^A-Z0-9]/gi, "").toUpperCase();
	const claimed = await browser.fetch(`/fs/api/auth/device?user_code=${encodeURIComponent(userCode)}`);
	const approved = await browser.write("/fs/api/auth/device/approve", { method: "POST", body: { userCode } });
	const exit = await Promise.race([exited, sleep(60_000).then(() => "timeout")]);
	if (exit === "timeout") child.kill();
	return { exit, out, err, url, userCode, claimed: claimed.status, approved: approved.status };
}

function modeOf(path) {
	return statSync(path).mode & 0o777;
}

function walk(root) {
	const out = [];
	if (!existsSync(root)) return out;
	for (const entry of readdirSync(root, { withFileTypes: true })) {
		const path = join(root, entry.name);
		if (entry.isDirectory()) out.push(...walk(path));
		else out.push(path);
	}
	return out;
}

// ------------------------------------------------------------------------------------------------ the journey

async function run(stack, cli) {
	const site = stack.accounts;
	const homeA = join(DIR, "homes", "A");
	const homeB = join(DIR, "homes", "B");
	const folderA = join(homeA, "robotparts");
	for (const dir of [homeA, homeB, folderA]) mkdirSync(dir, { recursive: true });

	// 0. signed out: nothing
	check("signed out: GET /fs/v1/me is 401", (await fetch(`${site}/fs/v1/me`)).status === 401);
	check("signed out: POST /fs/v1/credentials is 401", (await fetch(`${site}/fs/v1/credentials`, { method: "POST" })).status === 401);

	// 1. person A signs in on the page (email code in dev)
	const a = await signIn(site, PEOPLE.A);
	const meA = await (await a.fetch("/fs/v1/me")).json();
	const root = `users/${meA.user?.id}/`;
	check("A signed in by email code: /fs/v1/me names A and the root users/<id>/", meA.user?.email === PEOPLE.A && meA.root === root && meA.app === null, meA);
	check("A's cookie is folder-sync's own (folder-sync.session_token), not a bare better-auth one", [...a.jar.keys()].some((k) => k.endsWith("folder-sync.session_token")), [...a.jar.keys()]);
	check("a browser cookie never gets storage keys (POST /fs/v1/credentials with the cookie is 401)", (await a.write("/fs/v1/credentials", { method: "POST" })).status === 401);

	// 2. folder-sync login: the device grant, approved by A's browser session
	const signedIn = await login(cli, homeA, site, a);
	const accountPath = join(homeA, ".folder-sync", "account.json");
	check("folder-sync login prints the code and <server>/fs/device?user_code=…", !!signedIn.url && signedIn.url.startsWith(`${site}/fs/device?user_code=`), signedIn.url || `${signedIn.out}\n${signedIn.err}`);
	check("the browser claims and approves the code through Better Auth (GET /device, POST /device/approve)", signedIn.claimed === 200 && signedIn.approved === 200, { claimed: signedIn.claimed, approved: signedIn.approved });
	check("folder-sync login exits 0 once approved", signedIn.exit === 0, `${signedIn.out.trim().split("\n").pop()} ${signedIn.err.trim()}`);
	const account = existsSync(accountPath) ? JSON.parse(readFileSync(accountPath, "utf8")) : null;
	check("account.json is folder-sync-account/1 for A at this server, mode 0600", account?.schema === "folder-sync-account/1" && account.server === site && account.user?.id === meA.user?.id && existsSync(accountPath) && modeOf(accountPath) === 0o600, account && { schema: account.schema, server: account.server, user: account.user });
	check("the session token is printed nowhere", !!account?.token && !signedIn.out.includes(account.token) && !signedIn.err.includes(account.token));
	const agents = spawnSync(process.execPath, [join(ACCOUNTS, "node_modules", "wrangler", "bin", "wrangler.js"), "d1", "execute", "DB", "--local", "--persist-to", join(STATE, "d1"),
		"--config", join(ACCOUNTS, "wrangler.toml"), "--json", "--command", "SELECT userAgent FROM session"], { cwd: ACCOUNTS, encoding: "utf8", env: { ...process.env, CI: "1", WRANGLER_SEND_METRICS: "false" } });
	const stored = (() => { try { return JSON.parse(agents.stdout)[0].results.map((r) => r.userAgent); } catch { return []; } })();
	check("the machine's session in D1 names it: User-Agent folder-sync/<version> (<host>; linux)", stored.some((ua) => /^folder-sync\/v0-proof \([^;)]+; linux\)$/.test(ua || "")), stored);
	const whoami = fsync(cli, homeA, site, ["whoami"]);
	check("folder-sync whoami names A", whoami.code === 0 && whoami.out.includes(PEOPLE.A), whoami.out.trim() || whoami.err.trim());
	const creds = fsync(cli, homeA, site, ["credentials"]);
	let minted = null;
	try { minted = JSON.parse(creds.out); } catch { /* checked below */ }
	check("folder-sync credentials prints credential-process JSON for A's root", creds.code === 0 && minted?.Version === 1 && minted.Prefix === root && minted.Bucket === stack.bucket && minted.Endpoint === stack.endpoint, minted ? { Prefix: minted.Prefix, Bucket: minted.Bucket, Endpoint: minted.Endpoint } : creds.err);

	// 3. init + sync, with no key anywhere: folder-sync is its own credential process
	const init = fsync(cli, homeA, site, ["init", "--project", PROJECT, "--dir", folderA]);
	check("folder-sync init --project robotparts reaches A's root with no key set", init.code === 0 && init.out.includes(`prefix "${root}"`), (init.out + init.err).trim().split("\n").slice(-2).join(" · "));
	const first = fsync(cli, homeA, site, ["sync", "--once", "--dir", folderA]);
	check("sync --once (the first round) exits 0", first.code === 0, (first.out + first.err).trim().split("\n").slice(-1)[0]);
	const session = join(homeA, ".folder-sync", "session.json");
	check("the short-lived keys are cached in ~/.folder-sync/session.json (0600), from folder-sync's own credentials", existsSync(session) && modeOf(session) === 0o600 && JSON.parse(readFileSync(session, "utf8")).creds?.Prefix === root);

	// 4. the web host: a browser's PUT lands on disk at <folder>/hosts/<web host id>/...
	const xText = `{"part": "M3x8 socket head", "saved": "${new Date().toISOString()}"}\n`;
	const refused = await a.fetch(`/fs/v1/folders/${PROJECT}/web/saved/x.json`, { method: "PUT", body: xText, raw: true, headers: { Origin: site } });
	check("a cookie write without X-Folder-Sync: 1 is refused (403 csrf)", refused.status === 403 && (await refused.json()).error === "csrf");
	const put = await a.write(`/fs/v1/folders/${PROJECT}/web/saved/x.json`, { method: "PUT", body: xText, raw: true, headers: { "Content-Type": "application/json" } });
	const putBody = put.ok ? await put.json() : await put.text();
	const webHost = putBody?.host;
	check("PUT /fs/v1/folders/robotparts/web/saved/x.json writes into a minted web host (UUID v4), seq 1", put.status === 200 && /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(webHost || "") && putBody.seq === 1 && putBody.path === "saved/x.json", putBody);
	const webManifestPath = join(STATE, "s3", stack.bucket, root, PROJECT, "hosts", webHost || "none", "manifest.json");
	const webManifest = existsSync(webManifestPath) ? JSON.parse(readFileSync(webManifestPath, "utf8")) : null;
	check("the web host's manifest is folder-sync-manifest/1, host_name web, listing saved/x.json", webManifest?.schema === "folder-sync-manifest/1" && webManifest.host_name === "web" && webManifest.host_id === webHost && webManifest.files?.some((f) => f.path === "saved/x.json"), webManifest && { seq: webManifest.seq, files: webManifest.files.map((f) => f.path) });
	const pulled = fsync(cli, homeA, site, ["sync", "--once", "--discover", "--dir", folderA]);
	const landed = join(folderA, "hosts", webHost || "none", "saved", "x.json");
	check("after a sync, the web file is on disk at <folder>/hosts/<web host id>/saved/x.json, byte for byte", pulled.code === 0 && existsSync(landed) && readFileSync(landed, "utf8") === xText, landed);

	// 5. a file written on disk is listed online and returned by the bundle
	const yText = `{"part": "608 bearing", "from": "the machine"}\n`;
	mkdirSync(join(folderA, "saved"), { recursive: true });
	writeFileSync(join(folderA, "saved", "y.json"), yText);
	const pushed = fsync(cli, homeA, site, ["sync", "--once", "--dir", folderA]);
	check("sync --once pushes saved/y.json", pushed.code === 0 && pushed.out.includes("saved/y.json"), pushed.out.trim().split("\n").slice(0, 3).join(" · "));
	const hostA = JSON.parse(readFileSync(join(homeA, ".folder-sync", "host.json"), "utf8")).id;
	const view = await (await a.fetch(`/fs/v1/folders/${PROJECT}`)).json();
	check("GET /fs/v1/folders/robotparts lists saved/y.json under A's machine and saved/x.json under the web host",
		view.owner === meA.user.id && view.visibility === "private"
		&& view.files?.some((f) => f.host === hostA && f.path === "saved/y.json")
		&& view.files?.some((f) => f.host === webHost && f.path === "saved/x.json")
		&& view.hosts?.some((h) => h.id === webHost && h.web === true && h.name === "web")
		&& view.hosts?.some((h) => h.id === hostA && h.web === false),
		{ hosts: view.hosts?.map((h) => `${h.id.slice(0, 8)}:${h.name}:${h.web}`), files: view.files?.map((f) => `${f.host.slice(0, 8)}/${f.path}`) });
	const bundle = await (await a.fetch(`/fs/v1/folders/${PROJECT}/bundle?prefix=saved/`)).json();
	check("the bundle (prefix saved/) returns y.json's text and x.json's", bundle.files?.some((f) => f.host === hostA && f.path === "saved/y.json" && f.text === yText) && bundle.files?.some((f) => f.host === webHost && f.text === xText), bundle.files?.map((f) => f.path));
	const one = await a.fetch(`/fs/v1/folders/${PROJECT}/files/${hostA}/saved/y.json`);
	check("GET …/files/<host>/saved/y.json returns the bytes with ETag \"<sha256>\" and private, no-store", one.status === 200 && (await one.text()) === yText && one.headers.get("Cache-Control") === "private, no-store" && /^"[0-9a-f]{64}"$/.test(one.headers.get("ETag") || ""));
	const listed = await (await a.fetch("/fs/v1/folders")).json();
	check("GET /fs/v1/folders lists robotparts (private) with both hosts", listed.folders?.some((f) => f.project === PROJECT && f.visibility === "private" && f.hosts.includes(hostA) && f.hosts.includes(webHost)), listed);

	// 6. another person
	const b = await signIn(site, PEOPLE.B);
	const ownerQ = `owner=${encodeURIComponent(meA.user.id)}`;
	for (const path of [`/fs/v1/folders/${PROJECT}?${ownerQ}`, `/fs/v1/folders/${PROJECT}/bundle?prefix=saved/&${ownerQ}`, `/fs/v1/folders/${PROJECT}/files/${hostA}/saved/y.json?${ownerQ}`]) {
		const answer = await b.fetch(path);
		const text = await answer.text();
		check(`B cannot read A's private folder: ${path.split("?")[0]} -> ${answer.status}`, answer.status === 404 && !text.includes("608 bearing"));
	}
	const bView = await (await b.fetch(`/fs/v1/folders/${PROJECT}`)).json();
	check("B's own robotparts is B's (empty), never A's", bView.owner !== meA.user.id && (bView.files || []).length === 0, bView);
	const anon = await fetch(`${site}/fs/v1/folders/${PROJECT}?${ownerQ}`);
	check("signed out, A's private folder is 401", anon.status === 401);
	const bAccess = await (await b.fetch(`/fs/v1/access?project=${PROJECT}&${ownerQ}`)).json();
	check("/fs/v1/access tells B: not allowed", bAccess.allowed === false && bAccess.role === null, bAccess);

	// 7. publish: public is readable signed out, and back to private
	const published = fsync(cli, homeA, site, ["publish", "--public", "--dir", folderA]);
	check("folder-sync publish --public sets the folder public (PATCH)", published.code === 0 && /public/.test(published.out), (published.out + published.err).trim().split("\n").pop());
	const open = await fetch(`${site}/fs/v1/folders/${PROJECT}/files/${hostA}/saved/y.json?${ownerQ}`);
	check("public: signed out reads A's file, cacheable", open.status === 200 && (await open.text()) === yText && open.headers.get("Cache-Control") === "public, max-age=60");
	const bPublic = await (await b.fetch(`/fs/v1/access?project=${PROJECT}&${ownerQ}`)).json();
	check("/fs/v1/access tells B: allowed, role public, root A's", bPublic.allowed === true && bPublic.role === "public" && bPublic.root === root, bPublic);
	const closed = fsync(cli, homeA, site, ["publish", "--private", "--dir", folderA]);
	check("folder-sync publish --private makes it private again; signed out is 401", closed.code === 0 && (await fetch(`${site}/fs/v1/folders/${PROJECT}?${ownerQ}`)).status === 401);

	// 8. a reader
	const granted = await a.write(`/fs/v1/folders/${PROJECT}/readers`, { method: "POST", body: { email: PEOPLE.B } });
	const asReader = await b.fetch(`/fs/v1/folders/${PROJECT}/bundle?prefix=saved/&${ownerQ}`);
	const readerBody = asReader.ok ? await asReader.json() : null;
	check("A grants B read: B's bundle of A's folder holds y.json", granted.status === 200 && readerBody?.files?.some((f) => f.text === yText));
	const bFolders = await (await b.fetch("/fs/v1/folders")).json();
	check("B's /fs/v1/folders lists A's robotparts under readable", bFolders.readable?.some((r) => r.owner === meA.user.id && r.project === PROJECT && r.role === "reader"), bFolders.readable);
	const revoked = await a.write(`/fs/v1/folders/${PROJECT}/readers/${encodeURIComponent(PEOPLE.B)}`, { method: "DELETE" });
	check("A revokes B: 404 again", revoked.status === 200 && (await b.fetch(`/fs/v1/folders/${PROJECT}?${ownerQ}`)).status === 404);

	// 9. the web host's delete: _trash/, and it leaves the machine
	const del = await a.write(`/fs/v1/folders/${PROJECT}/web/saved/x.json`, { method: "DELETE" });
	const delBody = del.ok ? await del.json() : null;
	const trash = walk(join(STATE, "s3", stack.bucket, root, "_trash", PROJECT, webHost || "none")).filter((p) => p.endsWith(join("saved", "x.json")));
	check("DELETE …/web/saved/x.json moves it to _trash/<project>/<web host>/<stamp>/ (seq 2)", del.status === 200 && delBody?.seq === 2 && trash.length === 1 && readFileSync(trash[0], "utf8") === xText, { status: del.status, trash: trash.map((p) => p.slice(p.indexOf("_trash"))) });
	const after = fsync(cli, homeA, site, ["sync", "--once", "--dir", folderA]);
	check("after a sync, the deleted web file is gone from the machine", after.code === 0 && !existsSync(landed));

	// 10. the stand-in: every request it let through used a short-lived key inside its own root
	const gate = readFileSync(join(STATE, "gate.jsonl"), "utf8").trim().split("\n").map((l) => JSON.parse(l));
	const allowed = gate.filter((e) => e.allowed);
	const outside = allowed.filter((e) => [e.object, e.list_prefix, (e.copy_from || "").replace(`${stack.bucket}/`, "")].some((key) => key && !key.startsWith(e.prefixes?.[0] ?? "\u0000")));
	check("the R2 stand-in: everything it let through was a short-lived key, inside its own prefix", allowed.length > 10 && allowed.every((e) => e.temporary) && outside.length === 0, `${allowed.length} allowed, ${outside.length} outside`);
	const k = JSON.parse(readFileSync(join(STATE, "keys.json"), "utf8"));
	const leaked = walk(homeA).filter((f) => readFileSync(f).includes(k.parentSecret));
	check("the R2 parent secret is nowhere in A's HOME", leaked.length === 0, leaked);

	// 11. sign out: the machine, then the browser
	const out = fsync(cli, homeA, site, ["logout"]);
	check("folder-sync logout deletes account.json", out.code === 0 && !existsSync(accountPath), out.out.trim());
	const afterLogout = fsync(cli, homeA, site, ["credentials"]);
	check("after logout, folder-sync credentials exits 3", afterLogout.code === 3, afterLogout.err.trim());
	const stale = await fetch(`${site}/fs/v1/credentials`, { method: "POST", headers: { Authorization: `Bearer ${account?.token}` } });
	check("the machine's old bearer token is dead on the server (401)", !!account?.token && stale.status === 401);
	const before = a.cookie();
	const signOut = await a.write("/fs/v1/sign-out", { method: "POST" });
	check("POST /fs/v1/sign-out (cookie + X-Folder-Sync) answers 200 and clears the cookie", signOut.status === 200 && !a.cookie().includes("session_token"), a.cookie());
	const meAfter = await fetch(`${site}/fs/v1/me`, { headers: { Cookie: before } });
	check("signed out: /fs/v1/me is 401, even with the old cookie replayed", meAfter.status === 401);
}

const verb = process.argv[2] || "all";
let code = 0;
mkdirSync(DIR, { recursive: true });
try {
	if (verb === "all") rmSync(join(DIR, "homes"), { recursive: true, force: true });
	const cli = buildCli();
	const stack = dev("up");
	console.log(`stack: ${JSON.stringify({ accounts: stack.accounts, endpoint: stack.endpoint, bucket: stack.bucket })}`);
	await run(stack, cli);
} catch (error) {
	console.error(error);
	check("the proof ran to the end", false, String(error && error.message || error));
} finally {
	if (verb === "all") {
		try { dev("down"); } catch (error) { console.error(error); }
	}
	const failed = checks.filter((c) => !c.ok);
	writeFileSync(join(DIR, "proof.json"), JSON.stringify({ when: new Date().toISOString(), checks, passed: checks.length - failed.length, failed: failed.length }, null, 1));
	console.log(`\n${checks.length - failed.length}/${checks.length} checks passed; proof.json in ${DIR}`);
	code = failed.length ? 1 : 0;
}
process.exit(code);
